package dao;import model.*;import java.sql.*;import java.util.*;import util.Passwords;
public class MemberDAO5 extends DAO5{public MemberDAO5(Connection c){super(c);}public Member5 login(String u,String pass)throws Exception{try(PreparedStatement p=stmt("SELECT * FROM tblMember5 WHERE Username=?",u);ResultSet r=p.executeQuery()){if(!r.next()||!Passwords.verify(pass,r.getString("Password")))return null;int id=r.getInt("id");List<ManagementStaff5>a=query(ManagementStaff5.class,"SELECT m.*,s.MaNhanVien,q.PhanQuyen,q.VaiTro FROM tblMember5 m JOIN tblStaff5 s ON s.id=m.id JOIN tblManagementStaff5 q ON q.id=s.id WHERE m.id=?",id);if(!a.isEmpty())return a.get(0);return customer(id);}}public Customer5 customer(int id)throws Exception{List<Customer5>a=query(Customer5.class,"SELECT m.*,c.MaKhachHang FROM tblMember5 m JOIN tblCustomer5 c ON c.id=m.id WHERE m.id=?",id);if(a.isEmpty())throw new IllegalArgumentException("Không tìm thấy khách hàng");Customer5 c=a.get(0);c.setThe(new MembershipCardDAO5(con).forCustomer(id));return c;}}
